import { RIVET_PAGE_DATA_ELEMENT_ID } from '../types/rivet-page-types';

const PAGE_DATA_PATTERN = new RegExp(
  `<script id="${RIVET_PAGE_DATA_ELEMENT_ID}" type="application/json">([\\s\\S]*?)</script>`,
);

export const readRivetPageData = (html: string): unknown => {
  const data = html.match(PAGE_DATA_PATTERN)?.[1];
  if (data === undefined) throw new Error('Rivet page data is missing');
  return JSON.parse(data);
};

export const readRivetPageHead = (
  html: string,
): { title: string | null; robots: string | null } => ({
  title: html.match(/<title>([\s\S]*?)<\/title>/)?.[1] ?? null,
  robots: html.match(/<meta name="robots" content="([^"]*)" \/>/)?.[1] ?? null,
});
